import { studioGapContent } from './gapLessons';

export type MasteryUnit = {
  id: string; title: string; idea: string; conditions: string; method: string[];
  problem: string; solution: string[]; calculation: {prompt:string;answer:number};
  misconception: string; explanation: string; investigation: string; href: string;
};
export type MasteryCourse = {outcomes:string[];capstone:{prompt:string;solution:string};units:MasteryUnit[]};
const unit=(title:string,idea:string,conditions:string,method:string[],problem:string,solution:string[],calculation:[string,number],misconception:string,explanation:string,investigation:string,href:string):MasteryUnit=>({
  id:title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),title,idea,conditions,method,problem,solution,
  calculation:{prompt:calculation[0],answer:calculation[1]},misconception,explanation,investigation,href
});
const course=(outcomes:string[],prompt:string,solution:string,units:MasteryUnit[]):MasteryCourse=>({outcomes,capstone:{prompt,solution},units});
